import{_ as e,C as l,o as a,c as n,j as d,a as s,E as r,a2 as P}from"./chunks/framework.DGvnA5EY.js";const i="/workbuddy-guide/assets/01-office-trio.C3DeqUsW.png",W=JSON.parse('{"title":"第 11 章 办公三件套：Word、Excel、PPT","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 办公三件套是多数人第一次感受到 WorkBuddy 价值的地方。但很多人第一次用就失望： \\"它写得太模板了\\"\\"数字对不上\\"\\"PPT 丑\\"。根因通常不是模型不会写，而是你没把 交付标准说清楚…","frontmatter":{"title":"第 11 章 办公三件套：Word、Excel、PPT"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 办公三件套：Word、Excel、PPT/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 办公三件套：Word、Excel、PPT/index.md","lastUpdated":1791629861000}'),c={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 办公三件套：Word、Excel、PPT/index.md"};function p(u,t,x,g,T,k){const o=l("Paywall");return a(),n("div",null,[t[0]||(t[0]=d("h1",{id:"第-11-章-办公三件套-word、excel、ppt",tabindex:"-1"},[s("第 11 章 办公三件套：Word、Excel、PPT "),d("a",{class:"header-anchor",href:"#第-11-章-办公三件套-word、excel、ppt","aria-label":'Permalink to "第 11 章 办公三件套：Word、Excel、PPT"'},"​")],-1)),t[1]||(t[1]=d("blockquote",null,[d("p",null,"内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）")],-1)),r(o,{part:"2",variant:"banner"}),t[2]||(t[2]=P('<p>办公三件套是多数人第一次感受到 WorkBuddy 价值的地方。但很多人第一次用就失望： &quot;它写得太模板了&quot;&quot;数字对不上&quot;&quot;PPT 丑&quot;。<strong>根因通常不是模型不会写，而是你没把 交付标准说清楚</strong>，或者没选对技能、没走对流程。</p><p>这一章带你把三类最常见的办公产物——Word 文档、Excel 表格、PPT 汇报——跑通到 &quot;能直接交出去&quot;的程度，并顺手把&quot;团建策划&quot;这类重复活固化成你自己的零成本技能。</p><p><img src="'+i+'" alt="一只小黑左手举着文档、右手举着表格和幻灯片，像端着办公三件套" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;办公三件套&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这次办公任务要交付什么" tabindex="-1">一、先想清楚：这次办公任务要交付什么 <a class="header-anchor" href="#一、先想清楚-这次办公任务要交付什么" aria-label="Permalink to &quot;一、先想清楚：这次办公任务要交付什么&quot;">​</a></h2><p>动手前用五问定标（详见本篇导读）给任务定标。很多&quot;AI 做得不好&quot;的办公任务， 卡在没说清下面这张表：</p><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>这份材料帮谁做什么决定</td><td>给部门负责人看，判断项目是否继续投入</td></tr><tr><td>受众</td><td>阅读者是谁、懂不懂背景</td><td>管理层只看结论；项目组需要过程和责任人</td></tr><tr><td>材料</td><td>哪些是事实来源、哪些只是参考</td><td><code>data.xlsx</code> 是唯一数据口径，旧版 PPT 只参考结构</td></tr><tr><td>格式</td><td>要 Word、Excel、PPT，还是三者联动</td><td>一份复盘 Word + 一张风险台账 Excel + 8 页汇报 PPT</td></tr><tr><td>验收</td><td>怎么判断结果可用</td><td>数字能回源、公式可刷新、PPT 投屏不溢出</td></tr></tbody></table><h2 id="二、先选对-skill-办公任务的推荐组合" tabindex="-1">二、先选对 Skill：办公任务的推荐组合 <a class="header-anchor" href="#二、先选对-skill-办公任务的推荐组合" aria-label="Permalink to &quot;二、先选对 Skill：办公任务的推荐组合&quot;">​</a></h2><p>SkillHub 上有大量办公、文档、表格、PPT、会议纪要相关技能。先认准官方源安装， 再按场景挑。一个实用搭配思路：<strong>本地文件优先 Word/DOCX、Excel/XLSX、 Powerpoint/PPTX；在线协作用腾讯文档或 kdocs；材料多时先 Markdown Converter 抽取结构；会议类叠加腾讯会议或纪要类技能。</strong></p><table tabindex="0"><thead><tr><th>Skill 名称</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>Word / DOCX</strong></td><td>Word 文档</td><td>新建、检查、编辑 docx，处理标题、编号、表格、修订记录</td><td>适合本地 docx 文件</td></tr><tr><td><strong>Excel / XLSX</strong></td><td>Excel 表格</td><td>读取、清洗、写入工作簿，处理公式、日期、格式、模板保留</td><td>先确认数据口径</td></tr><tr><td><strong>Powerpoint / PPTX</strong></td><td>PPT 文件</td><td>创建、编辑、检查 pptx，处理版式、占位符、备注、图表、视觉质检</td><td>生成后仍要人工审稿</td></tr><tr><td><strong>Office Document Specialist Suite</strong></td><td>Word/Excel/PPT 综合</td><td>综合处理 Office 文件，适合自动化报告和多文件联动</td><td>复杂任务建议分步验收</td></tr><tr><td><strong>wps</strong></td><td>WPS 三件套</td><td>面向中国用户的 WPS 文字、表格、演示工作流</td><td>适合 WPS 生态用户</td></tr><tr><td><strong>腾讯文档 TENCENT DOCS</strong></td><td>在线协作</td><td>创建、读取、编辑、搜索腾讯文档（在线 Word/Excel/幻灯片）</td><td>通常需要授权</td></tr><tr><td><strong>kdocs skill</strong></td><td>金山/WPS 云文档</td><td>处理 WPS 云文档、智能文档、表格、PPT、PDF、知识库</td><td>通常需要 API Key</td></tr><tr><td><strong>Markdown Converter</strong></td><td>材料解析</td><td>把 PDF/Word/PPT/Excel 转成 Markdown，让模型先理解内容</td><td>适合读材料，不等于最终排版</td></tr><tr><td><strong>PPT Generator / PPT Workflow</strong></td><td>PPT 生成</td><td>从主题、讲稿或材料自动生成演示稿，适合初稿和结构化汇报</td><td>生成后仍需审稿</td></tr><tr><td><strong>Excel 公式生成</strong></td><td>公式问题</td><td>把自然语言转成 Excel/WPS/Google Sheets 公式并解释防错版本</td><td>公式要在样例数据上验证</td></tr><tr><td><strong>腾讯会议</strong></td><td>会议到文档</td><td>预约会议、取转写、取 AI 纪要，再转 Word 纪要/Excel 待办/PPT 汇报</td><td>需要会议平台授权</td></tr></tbody></table><blockquote><p><strong>零成本 Skill 入口</strong>：不知道装哪个，先装 <code>find-skills</code>，告诉它&quot;我每周做团建 策划、周报、数据透视&quot;，它帮你配装；跑顺的活再用 <code>skill-creator</code> 固化成专属技能 （完整示范见付费版）。</p></blockquote>',11)),r(o,{part:"2"}),t[3]||(t[3]=d("p",null,[d("em",null,"—— 以上试读到此为止。第二篇共 11 章，完整版 PDF 包含全部实操内容。——")],-1))])}const b=e(c,[["render",p]]);export{W as __pageData,b as default};
